sys_processor.script:
(function process(g_request, g_response, g_processor) {

	var strEngagement = g_request.getParameter('engagement');
	var aBacklog = CreateBacklog(strEngagement,true);

	if (aBacklog == false)
	{
		g_response.setStatus('404');
		return;
	}
	var strCsv = x_snc_devtools.MakeCsv(aBacklog,{ capital_headers: false, separator: ';' });
	var strFileName = 'backlog.csv';

	g_response.setContentType('text/csv');
	g_response.setHeader('Content-Disposition', 'attachment;filename=' + strFileName);
	g_processor.writeOutput(strCsv);

})(g_request, g_response, g_processor);
